const parent=$input.first().json;
const extraction=parent.extraction; const gap=parent.gap_analysis; const gate=parent.generation_gate; const errors=[];
if(parent.schema_version!=='1.0.0') errors.push('schema_version must be 1.0.0');
if(!parent.run_id||parent.run_id!==extraction?.run_id||parent.run_id!==gap?.run_id||parent.run_id!==gate?.run_id) errors.push('all run_id values must match');
if(!(parent.orchestration_context?.parent_trace_id||'').trim()) errors.push('parent_trace_id is required');
if(!['eligible_for_human_approval','eligible_with_tbd'].includes(gate?.gate_status)) errors.push('gate status is not eligible for review');
if(!['human_review','human_review_with_tbd'].includes(gate?.route)) errors.push('gate route is not a human-review route');
if(gate?.prd_generation_eligible!==true||gate?.human_approval_required!==true) errors.push('gate eligibility fields are inconsistent');
if(!['sufficient','partially_sufficient'].includes(gap?.information_sufficiency)||gap?.generation_allowed!==true||!['proceed','proceed_with_tbd'].includes(gap?.recommended_action)) errors.push('Gap Analysis is not eligible for review');
if(!Array.isArray(extraction?.items)||!Array.isArray(gap?.gaps)||!Array.isArray(gap?.risks)) errors.push('upstream arrays are invalid');
if(errors.length) throw new Error('Human Approval eligibility failed: '+errors.join('; '));
return [{json:{...parent,proposed_approved_item_ids:extraction.items.map(item=>item.id),eligible_tbd_ids:[...new Set([...gap.gaps.map(x=>x.id),...gap.risks.map(x=>x.id),...extraction.items.filter(x=>['dependency','risk'].includes(x.type)).map(x=>x.id)])],review_packet_created_at:new Date().toISOString()}}];

const packet=$('Validate Eligibility and Build Review Packet').first().json; const raw=$input.first().json;
const value=(key,label)=>raw[key]??raw[label]; const split=v=>String(v||'').split(',').map(x=>x.trim()).filter(Boolean); const verified=v=>v===true||v==='Verified'||(Array.isArray(v)&&v.includes('Verified'));
const reviewStatus=value('review_status','Review decision'); const reviewer=String(value('reviewer','Reviewer')||'').trim(); const approved=split(value('approved_item_ids','Approved item IDs (comma separated)')); const rejected=split(value('rejected_item_ids','Rejected item IDs (comma separated)')); const reviewedGaps=split(value('reviewed_gap_ids','Reviewed gap IDs (comma separated)')); const controlledTbds=split(value('controlled_tbd_ids','Controlled TBD IDs (comma separated)')); const conditionText=String(value('condition_description','Approval condition')||'').trim();
const checks={source_grounding_verified:verified(value('source_grounding_verified','Source grounding verified')),exact_values_verified:verified(value('exact_values_verified','Exact values verified')),relationships_verified:verified(value('relationships_verified','Relationships verified')),gap_analysis_verified:verified(value('gap_analysis_verified','Gap analysis verified')),unsupported_claims_absent:verified(value('unsupported_claims_absent','Unsupported claims absent'))};
const itemIds=packet.extraction.items.map(x=>x.id); const gapIds=packet.gap_analysis.gaps.map(x=>x.id); const allowedTbdIds=packet.eligible_tbd_ids; const routeMap={approved:'prd_generation',approved_with_conditions:'prd_generation_with_conditions',changes_requested:'correction',clarification_required:'clarification',rejected:'stopped'}; const errors=[];
if(!reviewer) errors.push('reviewer is required'); if(!routeMap[reviewStatus]) errors.push('unsupported review decision'); if([...approved,...rejected].some(id=>!itemIds.includes(id))) errors.push('approved/rejected IDs must exist upstream'); if(reviewedGaps.some(id=>!gapIds.includes(id))) errors.push('reviewed gap IDs must exist upstream'); if(controlledTbds.some(id=>!allowedTbdIds.includes(id))) errors.push('controlled TBD IDs must exist upstream'); if(approved.some(id=>rejected.includes(id))) errors.push('approved and rejected IDs overlap');
if(['approved','approved_with_conditions'].includes(reviewStatus)&&approved.length===0) errors.push('approval requires approved IDs'); if(reviewStatus==='approved'&&(rejected.length||controlledTbds.length||conditionText)) errors.push('standard approval cannot include rejection, TBD or condition'); if(reviewStatus==='approved_with_conditions'&&packet.generation_gate.gate_status!=='eligible_with_tbd') errors.push('conditional approval requires eligible_with_tbd'); if(reviewStatus==='approved_with_conditions'&&(!controlledTbds.length||!reviewedGaps.length||!conditionText)) errors.push('conditional approval requires gaps, TBDs and condition'); if(['approved','approved_with_conditions'].includes(reviewStatus)&&Object.values(checks).some(v=>!v)) errors.push('all five evidence checks must pass');
if(errors.length) throw new Error('Human approval validation failed: '+errors.join('; ')); const conditions=conditionText?[{id:'COND-001',description:conditionText,related_ids:[...new Set([...approved,...controlledTbds])]}]:[];
return [{json:{schema_version:'1.0.0',run_id:packet.run_id,review_status:reviewStatus,reviewer,reviewed_at:new Date().toISOString(),gate_status_reviewed:packet.generation_gate.gate_status,approved_item_ids:approved,rejected_item_ids:rejected,reviewed_gap_ids:reviewedGaps,controlled_tbd_ids:controlledTbds,conditions,evidence_checks:checks,review_notes:String(value('review_notes','Review notes')||''),next_route:routeMap[reviewStatus],validation:{structurally_valid:true,referenced_ids_valid:true,decision_consistent:true,validated_at:new Date().toISOString()}}}];
